# owner: platform
from typing import List, Tuple

from rosterkit.models import Student

def _check_arguments(
    students: List[Student], seats_per_row: int
) -> None:
    if seats_per_row <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")

def _name_key(student: Student) -> Tuple[str, str]:
    last = student.last_name.casefold()
    first = student.first_name.casefold()
    return (last, first)

def _seating_rows(
    students: List[Student], seats_per_row: int
) -> List[List[Student]]:
    ordered = sorted(students, key=_name_key)
    return [
        ordered[start:start + seats_per_row]
        for start in range(0, len(ordered), seats_per_row)
    ]

def _label_rows(rows: List[List[Student]]) -> List[str]:
    texts = []
    for number, members in enumerate(rows, start=1):
        names = [member.display_name for member in members]
        texts.append(f"Row {number}: " + " | ".join(names))
    return texts

# ---
def seat_rows(
    students: List[Student], seats_per_row: int
) -> List[str]:
    """One line per row, sorted by last name."""
    _check_arguments(students, seats_per_row)
    rows = _seating_rows(students, seats_per_row)
    return _label_rows(rows)
